mapper.select:
SELECT ext.spu_id FROM product_publication_spu_ext ext INNER JOIN product_spu spu ON spu.id = ext.spu_id AND spu.deleted = b'0' AND spu.biz_scene = 'PUBLICATION'
INNER JOIN product_sku sku ON sku.spu_id = spu.id AND sku.deleted = b'0' INNER JOIN product_publication_sku_grade_rel grade_rel ON grade_rel.sku_id = sku.id AND grade_rel.deleted = b'0' AND grade_rel.grade_catalog_id = #{req.gradeCatalogId}
WHERE ext.deleted = b'0'
AND ext.publisher_id = #{req.publisherId}
AND ext.publication_type_id = #{req.publicationTypeId}
AND ext.issue_cycle = #{req.issueCycle}
AND spu.name LIKE CONCAT('%', #{req.productName}, '%')
AND EXISTS ( SELECT 1 FROM product_spu_category_rel category_rel WHERE category_rel.spu_id = spu.id AND category_rel.deleted = b'0' AND category_rel.category_id IN
#{categoryId}
)
GROUP BY ext.spu_id ORDER BY MAX(spu.sort) DESC, ext.spu_id DESC
